"use client";

/**
 * The calc strings, kept out of the shared dictionary.
 *
 * All three languages of every string used to sit in one module that every
 * page imports, so a radiologist writing a report downloaded and parsed the
 * whole thing — 44% of it being calculator labels, staging tables and critical-findings text. Registering them from here
 * means they travel with the code that needs them: this module is imported
 * by that feature alone, so the bundler puts them in its chunk.
 */

import { registerMessages } from "./i18n";

